        if (object instanceof EvalContext) {
            final EvalContext ctx = (EvalContext) object;
            final Pointer ptr = ctx.getSingleNodePointer();
            return ptr == null ? Double.NaN : doubleValue(ptr);
        }
        return doubleValue(stringValue(object));
    }

